(()=>{
  'use strict';
  const D=window.WORLD_DATA,A=window.WORLD_ART,root=document.getElementById('world-app'),KEY='ppm_spotlight6_module2bcd_v1';
  const courseKeys=[KEY,'ppm_spotlight6_module1_v2','ppm_spotlight6_module2a_v1','ppm_spotlight6_skills_v2','ppm_spotlight6_sidequests_v1'];
  const fresh=()=>({unit:'b',stage:null,tab:'learn',answers:{},checks:{},attempts:{},hints:{},reveals:{},done:{},fields:{},open:{},games:{},object:'sofa',labels:false,wordGroup:'furniture',street:'oxford',notes:{}});
  let s=fresh(),storageOK=true,modal='',lastFocus=null;
  try{s={...s,...JSON.parse(localStorage.getItem(KEY)||'{}')};if(!D.units[s.unit])s.unit='b';}catch{storageOK=false;}
  const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm=(v='')=>String(v).trim().toLowerCase().replace(/[’‘]/g,"'").replace(/[–—-]/g,' ').replace(/[.!?,]+$/,'').replace(/\s+/g,' ');
  const shuffle=a=>{const r=[...a];for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]];}return r;};
  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(s));}catch{storageOK=false;}};
  const value=(k,def='')=>s.fields[k]??def;
  const unit=()=>D.units[s.unit];
  const count=()=>unit().stages.filter(id=>s.done[id]).length;
  const note=(title,body)=>`<aside class="callout"><b>${title}</b>${body}</aside>`;
  const fold=(title,body)=>`<details data-fold="${esc(title)}" ${s.open[title]?'open':''}><summary>${title}</summary>${body}</details>`;
  const table=(head,rows)=>`<div class="tablewrap"><table><thead><tr>${head.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const area=(key,label,placeholder='')=>`<label class="field">${label}<textarea data-field="${key}" placeholder="${esc(placeholder)}">${esc(value(key))}</textarea></label>`;
  const input=(key,label,def='')=>`<label class="field">${label}<input data-field="${key}" value="${esc(value(key,def))}" autocomplete="off"></label>`;
  const checkList=(prefix,items)=>`<div class="checklist">${items.map((t,i)=>`<label><input type="checkbox" data-field="${prefix+i}" ${value(prefix+i)?'checked':''}>${t}</label>`).join('')}</div>`;
  const keks=t=>`<aside class="keks-note"><img src="./assets/keks/keks-skeptical.webp" alt="Фирменный Кекс помогает разобраться в задании"><p><strong>KEKS / NEED A CLUE?</strong>${t}</p></aside>`;
  const bridge=(st,tu)=>`<div class="aftertask"><div class="turn"><b>STUDENT TURN</b><p>${st}</p></div><div class="turn"><b>ASK YOUR TUTOR / SWITCH ROLES</b><p>${tu}</p></div></div>`;
  function speak(text){if(!window.speechSynthesis){toast('Озвучка недоступна. Прочитайте с преподавателем.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=.88;u.voice=speechSynthesis.getVoices().find(v=>v.lang==='en-GB')||null;u.onerror=()=>toast('Голос недоступен. Преподаватель может прочитать текст.');speechSynthesis.speak(u);}
  const stop=()=>window.speechSynthesis?.cancel();
  function toast(msg){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),3200);}
  function tabs(id){if(id==='delivery')return [['play','01 · ПОРУЧЕНИЯ'],['use','02 · РАЗГОВОР']];if(['roomStudio','townStudio','guide'].includes(id))return [['studio','МАСТЕРСКАЯ']];if(['roomExit','visitors'].includes(id))return [['play','ИССЛЕДУЕМ И ИГРАЕМ']];if(id==='streets')return [['learn','ТЕКСТ + ЗАДАНИЕ']];if(['moving','town'].includes(id))return [['learn','01 · ЧИТАЕМ'],['play','02 · ТЕКСТ + ЗАДАНИЕ']];if(id==='listening')return [['learn','01 · СЛУШАЕМ'],['play','02 · СЛУШАЕМ И НАХОДИМ']];if(['codes','pronunciation'].includes(id))return [['learn','01 · РАЗБЕРЁМСЯ'],['play','02 · ИГРАЕМ']];return [['learn','01 · РАЗБЕРЁМСЯ'],['play','02 · ИГРАЕМ'],['use','03 · ПРО ТЕБЯ']];}
  function route(u,st=null,tab='learn'){stop();s.unit=D.units[u]?u:'b';s.stage=unit().stages.includes(st)?st:null;s.tab=s.stage&&tabs(s.stage).some(([t])=>t===tab)?tab:s.stage?tabs(s.stage)[0][0]:'learn';save();history.replaceState(null,'','#'+s.unit+(s.stage?'/'+s.stage+'/'+s.tab:''));render();window.scrollTo(0,0);root.querySelector('h1')?.focus({preventScroll:true});}
  function readHash(){const[u,st,tab]=location.hash.slice(1).split('/');if(D.units[u]){s.unit=u;s.stage=D.units[u].stages.includes(st)?st:null;s.tab=tab||'learn';}}
  function render(){if(s.stage&&!unit().stages.includes(s.stage))s.stage=null;if(s.stage&&!tabs(s.stage).some(([t])=>t===s.tab))s.tab=tabs(s.stage)[0][0];const focused=document.activeElement,bookmark=focused&&root.contains(focused)?Object.entries(focused.dataset).find(([k])=>k!=='field'&&k!=='gameInput'):null;
    root.innerHTML=`${!storageOK?'<div class="storage-warning" role="status">Браузер не разрешает сохранение. Прогресс останется только до закрытия вкладки.</div>':''}<header class="top"><a class="brand" href="./index.html">VICTORIA / ENGLISH STUDIO<small>SPOTLIGHT 6 · MODULE 2b–2d</small></a><nav class="topnav" aria-label="Инструменты"><a class="btn" href="./module1.html">MODULE 1</a><a class="btn" href="./index.html">2A / HAPPY TIMES</a><button data-home>КАРТА ${unit().code.toUpperCase()}</button><button data-modal="tutor">TUTOR NOTES</button><button data-modal="reset">NEW STUDENT / RESET ALL</button></nav></header><div class="progress" role="progressbar" aria-label="Прогресс ${unit().code}" aria-valuemin="0" aria-valuemax="${unit().stages.length}" aria-valuenow="${count()}"><i style="width:${count()/unit().stages.length*100}%"></i></div><main class="wrap" id="main"><nav class="unit-links" aria-label="Разделы Module 2"><a class="btn" href="./index.html">2a · Happy times</a>${Object.entries(D.units).map(([id,u])=>`<a href="#${id}" class="btn ${id===s.unit?'current':''}" ${id===s.unit?'aria-current="page"':''}>${u.code} · ${u.name}</a>`).join('')}</nav>${s.stage?stageView():home()}<footer class="footer">VICTORIA · Interactive English Website Studio · ${unit().code.toUpperCase()} · Статический сайт: прогресс сохраняется только в этом браузере. Озвучка — дополнительный голос устройства с чтением преподавателя как альтернативой. <a href="./SOURCES-MODULE2BCD.md">Источники и примечания</a>.</footer></main><div class="modal" ${modal?'':'hidden'}><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="world-dialog-title"><button class="close" data-close aria-label="Закрыть">×</button>${modal==='reset'?resetView():tutorView()}</section></div>`;
    bind();if(modal)root.querySelector('.close')?.focus();else if(bookmark){const[k,v]=bookmark;const el=[...root.querySelectorAll('button,a')].find(x=>x.dataset[k]===v&&!x.disabled);el?.focus({preventScroll:true});}
  }
  function home(){const u=unit();return `<section class="world-hero"><div><div class="kicker">Spotlight 6 · ${u.code} · Pages ${u.pages} · A1+ → A2</div><h1 tabindex="-1">${u.concept.split(' ').slice(0,-1).join(' ')}<br><span>${u.concept.split(' ').slice(-1)}</span></h1><p><b>${u.tag}</b></p><p>${u.outcome}</p><p class="small">Core Route: ${u.time}. Дополнительные серии можно пропускать. Ни жизней, ни штрафов за ошибки.</p><div class="actions"><button class="primary" data-stage="${u.stages.find(id=>!s.done[id])||u.stages[0]}">${count()?'ПРОДОЛЖИТЬ →':'ОТКРЫТЬ ПЕРВОЕ ДЕЛО →'}</button></div></div>${s.unit==='b'?A.room('',true):s.unit==='c'?cityMap('preview'):`<div class="world-poster"><img src="./assets/keks/keks-reading.webp" alt="Кекс изучает материалы для туристического журнала"><div class="kicker">YOUR EDITORIAL DESK</div><h2>LONDON.<br>LOS ANGELES.<br>NEW YORK.</h2><p>Прочитай три файла. Выбери улицу для посетителя. Напиши свой мини-гид.</p></div>`}</section><div class="sectionhead"><div><div class="kicker">Lesson map / ${count()} из ${u.stages.length}</div><h2>${u.name}</h2></div><p>Нажми любой этап. Учись через контекст, затем пробуй, играй и используй язык в своей речи.</p></div><div class="map world-map">${u.stages.map((id,i)=>`<button data-stage="${id}"><span class="num">${String(i+1).padStart(2,'0')} ${s.done[id]?'✓ ГОТОВО':''}</span><b>${D.stages[id][0]}</b><small>${D.stages[id][1]}</small></button>`).join('')}</div>${keks(s.unit==='b'?'Передвинуть диван легко. Объяснить, куда именно, — наша английская задача.':s.unit==='c'?'Сначала найди магазин на карте. Затем объясни, где он.': 'Хороший гид различает факт из текста и свою догадку.')}`;}
  function stageView(){const id=s.stage,ix=unit().stages.indexOf(id);return `<div class="lesson-layout"><aside class="rail"><button class="railhome" data-home>← КАРТА ${unit().code.toUpperCase()}</button><nav aria-label="Этапы">${unit().stages.map((x,i)=>`<button data-stage="${x}" class="${x===id?'active':''}" ${x===id?'aria-current="step"':''}>${String(i+1).padStart(2,'0')} ${D.stages[x][1]} ${s.done[x]?'✓':''}</button>`).join('')}</nav><div class="mini"><b>CORE + EXTRA</b><p>Одна основная игра и один речевой шаг. Extra Practice оставь на повторение.</p></div></aside><div class="world-main"><section class="stage-heading"><div><div class="kicker">${unit().code} · ${unit().name}</div><h1 tabindex="-1">${D.stages[id][0]}</h1><p>${D.stages[id][1]}</p></div><span class="count">${String(ix+1).padStart(2,'0')}</span></section>${tabs(id).length>1?`<nav class="tabs" aria-label="Режим этапа">${tabs(id).map(([t,label])=>`<button data-tab="${t}" class="${t===s.tab?'active':''}" ${t===s.tab?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`:''}<section class="panel">${s.tab==='learn'?learn(id):s.tab==='play'?play(id):s.tab==='studio'?studio(id):use(id)}</section><div class="stage-footer"><button data-step="-1" ${ix===0?'disabled':''}>← Назад</button><span class="status">${s.done[id]?'✓ Этап завершён':D.quizzes[id]?'Верно выполни Core Check или основную игру.':'Открытый результат обсуждаем с преподавателем.'}</span><button class="primary" data-step="1">${ix===unit().stages.length-1?'К карте →':'Дальше →'}</button></div></div></div>`;}
  function wordCards(group){return `<p class="small">Нажми карточку: перевод откроется. Сначала посмотри на слово и произнеси его, затем проверь значение.</p><div class="vocab">${D.words[group].map(([en,ru,ipa],i)=>`<div><button class="word" data-word="${group}|${i}" aria-expanded="${!!s.open['word:'+group+i]}"><strong lang="en">${en}</strong><small>${ipa}</small><span>${s.open['word:'+group+i]?ru:'Открыть перевод +'}</span></button><button class="quiet" data-say="${esc(en)}" aria-label="Прослушать ${esc(en)}">▷ Listen</button></div>`).join('')}</div>`;}
  function roomExplorer(){const all=[...D.words.furniture],w=all.find(x=>x[0]===s.object)||all[0];return `<div class="actions"><button data-labels>${s.labels?'СКРЫТЬ':'ПОКАЗАТЬ'} ПОДПИСИ НА ПЛАНЕ</button></div>${A.room(s.object,s.labels)}<div class="object-info" aria-live="polite"><strong>${w[0]}</strong><span>${w[2]} · ${w[1]}</span></div><div class="object-bank">${all.map(x=>`<button data-object="${x[0]}" class="${s.object===x[0]?'selected':''}">${x[0]}</button>`).join('')}</div><p class="world-source-note">Это наш учебный план, а не точная копия картинки учебника. Ceiling — потолок — в плане сверху не виден. Объекты можно выбирать кнопками, даже если на маленьком экране трудно попасть в рисунок.</p>`;}
  function learn(id){
    if(id==='rooms')return `<h2>Кекс переезжает. В какую комнату — что?</h2>${note('Context → notice',`<p class="example">We sleep in a <b>bedroom</b>.<br>We cook in a <b>kitchen</b>.<br>There’s a sofa in the <b>living room</b>.</p><p>Посмотри на план: здесь диван, кресло, журнальный столик. Как называется такая комната?</p>`)}${wordCards('rooms')}${roomExplorer()}${keks('Room — комната. Living room — гостиная. Study здесь означает кабинет, а не действие «учиться».')}`;
    if(id==='inventory')return `<h2>Object files / узнаём предметы.</h2>${roomExplorer()}<div class="game-switch">${[['furniture','Гостиная'],['home','Остальной дом']].map(([g,label])=>`<button data-word-group="${g}" class="${s.wordGroup===g?'selected':''}">${label}</button>`).join('')}</div>${wordCards(s.wordGroup)}${fold('Как запоминать слова через место',`<p>Свяжи новое слово с комнатой: fridge → kitchen, bathtub → bathroom, wardrobe → bedroom. Это опора для памяти, а не строгий запрет: компьютер и зеркало могут быть в разных комнатах.</p><p>Закрой перевод. Представь свой дом и скажи: <b>There’s a fridge in the kitchen.</b></p>`)}${fold('Похожие вещи — разные слова',table(['Слово','Как понять'],[['cushion','Декоративная подушка на диване/кресле.'],['cupboard','Шкафчик, например кухонный. P обычно не слышно: /ˈkʌb.əd/.'],['wardrobe','Шкаф для одежды.'],['bookcase / shelves','Книжный шкаф / полки. Shelf → shelves.'],['sink / basin','В этом уроке sink — кухонная раковина; basin — умывальник в ванной.'],['carpet / rug','В бытовом описании carpet — ковёр/ковровое покрытие; rug — отдельный небольшой ковёр. На нашем плане под столиком — rug.'],['furniture','Мебель — неисчисляемое: some furniture, не a furniture и не furnitures.']]))}`;
    if(id==='grammar')return grammarLearn();
    if(id==='place')return `<h2>Точное место решает всё.</h2><p class="example">Put the sofa <mark>in front of the window</mark>.<br>Put the book <mark>on the table</mark>.</p><p>Сначала посмотри, как меняется положение розового мяча. Это схемы: мяч здесь помогает увидеть значение предлога.</p><div class="relation-grid">${D.words.place.map(([en,ru,ipa])=>`<article class="relation-card">${A.relation(en)}<h3>${en}</h3><p>${ru} · ${ipa}</p><button class="quiet" data-say="${en}">▷ Listen</button></article>`).join('')}</div>${note('Не путай три ситуации',`<p><b>In</b> — внутри границ: flowers in a vase. <b>On</b> — на поверхности: a book on a table. <b>Under</b> — ниже, под предметом: a rug under the table.</p><p><b>Next to</b> — рядом, обычно на одной стороне. <b>Opposite</b> — напротив, например по другую сторону дороги. <b>Between A and B</b> — между двумя ориентирами. Не теряй <b>and</b>.</p>`)}${roomExplorer()}${fold('Что значит in front of / behind на нашем плане?',`<p>План смотрим сверху. Окно находится на дальней стене. Диван перед окном, журнальный столик перед диваном. Не путай <b>in front of</b> с <b>opposite</b>: столик перед диваном, а не на другой стороне улицы.</p>`)}${bridge('Скажи, где книга, цветы и ковёр на плане.','Преподаватель меняет предлог в одной фразе. Найди ошибку и исправь.')}`;
    if(id==='moving')return `<h2>Перед чтением: кто здесь и что происходит?</h2><p>Laura, Steve и John в новом доме. Steve и John переносят мебель, Laura помогает выбрать места. Прочитайте первые три реплики. Кто кому Dad? Что они собираются делать?</p>${movingWords()}${dialogue()}${note('Первое чтение — общая мысль',`<p>Не переводи каждую реплику. Найди: <b>людей</b>, <b>мебель</b> и <b>указания, куда её поставить</b>. Потом открой «Текст + задание»: там диалог останется рядом с вопросами.</p>`)}${fold('Коротко по-русски',`<p>Семья расставляет мебель в новой гостиной. Диван хотят поставить перед окном, кресло — между камином и дверью. Часы — на стене напротив дивана. Стол — между диваном и креслом. Ковёр Laura хочет под всей мебелью. John — сын Laura и Steve.</p>`)}<button class="primary" data-tab="play">ТЕКСТ + ЗАДАНИЕ →</button>`;
    if(id==='pronunciation')return `<h2>Один вопрос — одна нужная деталь.</h2>${table(['Вопросительное слово','Значение','Пример'],[['where /weə/','где','Where is the sofa?'],['who /huː/','кто','Who is he?'],['what /wɒt/','что / какой предмет','What is it?'],['which /wɪtʃ/','который из вариантов','Which bag is yours?'],['when /wen/','когда','When is your birthday?'],['whose /huːz/','чей','Whose bag is it?']])}${note('Что делает /w/?',`<p>Для /w/ округли губы, как для короткого «у», затем быстро переходи к гласному. Не касайся нижней губой зубов: так получится /v/.</p><p><b>we /wiː/, win /wɪn/, when /wen/, why /waɪ/</b> — звук /w/ есть. <b>Who /huː/, whose /huːz/</b> — буква w не произносится, начинаем с /h/.</p><div class="actions">${['we, win, when, why','who, whose','where, what, which, when'].map(t=>`<button data-say="${t}">▷ ${t}</button>`).join('')}</div><p class="small">Повтори за преподавателем, если голос устройства звучит неестественно.</p>`)}${bridge('Спроси о предмете на плане: What is it? Where is it?','Задай ещё вопрос с whose или when. Преподаватель ответит без показа текста.')}`;
    if(id==='shops')return `<h2>Где что можно купить или получить?</h2>${note('Сначала — понятная ситуация',`<p class="example">I need a stamp. → You can buy stamps <b>at the post office</b>.<br>I want to borrow a book. → Go to the <b>library</b>.</p><p>В магазине что-то покупаем, а в библиотеке книгу можно взять на время. В игре выбираем лучшее место по его специализации.</p>`)}${wordCards('shops')}${fold('6 вещей со страницы',wordCards('goods'))}${fold('Почему baker’s, а не просто baker?',`<p><b>Baker</b> — пекарь. <b>Baker’s</b> здесь означает магазин/пекарню этого специалиста: слово shop опускается. Так же <b>chemist’s, greengrocer’s, newsagent’s</b>. Апостроф в письме нужен; при проверке принимаются прямой и типографский варианты.</p><p>В американском английском вместо chemist’s обычно pharmacy/drugstore. Здесь тренируем британскую лексику учебника.</p>`)}${note('Полезные глаголы',`<p><b>buy</b> — купить; <b>get</b> — получить; <b>borrow</b> — взять на время; <b>send a letter</b> — отправить письмо; <b>withdraw money</b> — снять деньги. Past: <b>buy → bought</b>. Для дополнительного рассказа: <b>I bought bread at the baker’s last week.</b></p><p>Aspirin здесь только название товара в словарном задании. Мы не выбираем лекарство для лечения.</p>`)}${keks('Есть разница: купить книгу и взять книгу на время. Borrow a book → library.')}`;
    if(id==='town')return `<h2>Сначала предположи. Потом проверь по тексту.</h2><p>Выбери до шести слов, которые ожидаешь увидеть в тексте о районе. Это предположение, а не тест на оценку.</p>${prediction()}<div class="world-workspace"><div class="source-panel"><div class="kicker">TONY’S NEIGHBOURHOOD / ADAPTED LEARNING TEXT</div><p lang="en">${D.townText}</p>${fold('Перевод и ориентиры',`<p>Почта рядом с банком; магазин газет напротив банка; супермаркет напротив почты. Остановка позади супермаркета. Аптека рядом с супермаркетом; библиотека позади аптеки. Кофейня напротив аптеки.</p>`)}</div>${cityMap('preview')}</div>${mapLegend()}<button class="primary" data-tab="play">ТЕКСТ + ЗАДАНИЕ →</button>`;
    if(id==='listening')return `<h2>Local radio / новая учебная запись.</h2><p>Оригинальная аудиозапись учебника не приложена. Здесь новое сообщение для нашей карты. Его читает голос устройства или преподаватель из Tutor Notes.</p>${note('Как слушать',`<ol><li>Сначала найди стартовую точку: где начинается маршрут?</li><li>Второй раз слушай слова next to, opposite, behind.</li><li>В игре выбери место на карте, затем ответь на вопросы.</li></ol>`)}${input('listenPrediction','Предположи два слова, которые услышишь')}${listenControls()}${cityMap('listen')}${transcript()}<button data-tab="play">СЛУШАЕМ И НАХОДИМ →</button>`;
    if(id==='streets')return streetReading();
    if(id==='codes')return `<h2>Короткая запись, полный смысл.</h2><p>В адресе названия улиц часто сокращают. Нажми карточку, чтобы раскрыть полную форму.</p><div class="code-grid">${D.codes.map(([short,full,ru],i)=>`<button class="code-card" data-code="${i}" aria-expanded="${!!s.open['code'+i]}"><strong>${short}</strong><span>${s.open['code'+i]?full:'Открыть +'}</span><small>${s.open['code'+i]?ru:'street code'}</small></button>`).join('')}</div>${note('Важны и имя, и тип улицы',`<p><b>Oxford St</b> = Oxford Street.<br><b>Hollywood Blvd</b> = Hollywood Boulevard.<br><b>Wall St</b> = Wall Street.</p><p>Точки и формы сокращений могут различаться по стране и стилю. Здесь тренируем варианты из учебника. Не все типы улиц дословно совпадают с русскими названиями.</p>`)}<button data-tab="play">ОТКРЫТЬ CODE PRESS →</button>`;
    return play(id);
  }
  function grammarLearn(){return `<h2>От описания комнаты — к правилу.</h2><p class="example">There’s <mark>a sofa</mark>.<br>There are <mark>some cushions</mark>.<br>There aren’t <mark>any dining chairs</mark>.<br>Is there <mark>any water</mark> in the vase?</p><p>Сначала найди одну вещь, несколько вещей и вещество, которое не считаем по штукам. Затем сравни утверждение, отрицание и вопрос.</p>${table(['Ситуация','Форма','Пример'],[['Один исчисляемый предмет','a / an','a sofa · an armchair'],['Несколько предметов, утверждение','some','some cushions'],['Немного вещества, утверждение','some','some water'],['Обычный вопрос / отрицание','any','any cushions · any water']])}${fold('A или an? Слушаем первый звук',`<p><b>A</b> перед согласным звуком: a sofa, a table. <b>An</b> перед гласным: an armchair. Выбираем по <b>звуку</b>, не только по букве. Перед множественным числом a/an не ставим: не a cushions.</p>`)}${fold('Some и any — не «всегда» и не «никогда»',`<p>Для начала: в обычном утверждении — <b>some</b>; в обычном вопросе/отрицании — <b>any</b>. Но в просьбах и предложениях часто <b>some</b>: <b>Can I have some water, please?</b> Мы надеемся получить воду.</p><p><b>Any</b> может означать «любой» в утверждении: <b>Choose any room.</b> Это другое значение. <b>Water, furniture</b> не считаем как отдельные штуки: some water / some furniture.</p>`)}${note('There is / There are',`<p><b>There is</b> + один предмет или неисчисляемое: <b>There is a sofa / some water.</b><br><b>There are</b> + несколько: <b>There are some flowers.</b></p><p>Вопрос: <b>Is there…? / Are there…?</b><br>Отрицание: <b>There isn’t… / There aren’t…</b></p>`)}<h3>Кто-то или что-то?</h3><div class="word-types"><div><b>THING → вещь</b><p><b>something</b> — что-то<br><b>anything</b> — что-нибудь в вопросе; с отрицанием — ничего</p><p>There is something on the table.<br>I can’t see anything.</p></div><div><b>BODY / ONE → человек</b><p><b>somebody / someone</b> — кто-то<br><b>anybody / anyone</b> — кто-нибудь; с отрицанием — никто</p><p>Somebody is in the room.<br>Is there anyone in the room?</p></div></div>${fold('Форма глагола и частые ошибки',`<p>После somebody / someone / something и подобных форм — <b>единственное число</b>: <b>Somebody is… / Someone has…</b>, не somebody are.</p><p><b>Someone / anyone</b> уже означают человека. Не надо добавлять person: не somebody person. После английского отрицания не добавляем второе отрицание: <b>I can’t see anybody.</b></p>`)}${keks('Сначала спроси: одна вещь, несколько или вещество? Потом: утверждение, вопрос или отрицание?')}`;}
  function movingWords(){return table(['Фраза','Значение'],[['Can you give me a hand?','Поможешь мне? Не просьба «дать руку» буквально.'],['Quick!','Скорее!'],['That’s great!','Здорово!'],['Calm down.','Успокойся / не волнуйся.'],['What else?','Что ещё?'],['Watch out! / Be careful!','Осторожно!'],["We’re doing our best.",'Мы стараемся как можем.']]);}
  function dialogue(){return `<article class="source-panel"><div class="kicker">MOVE-IN / ADAPTED DIALOGUE</div>${D.dialogue.map(([who,line])=>`<div class="dialogue-line" lang="en"><span class="who">${who}</span>${line}</div>`).join('')}</article>`;}
  function mapLegend(){return note('Как читать нашу карту',`<p>Все здания обращены входами вниз. <b>Behind</b> на этой схеме — на один ряд выше, позади здания. <b>Opposite</b> — через широкую Main Street, в том же столбце. <b>Next to</b> — соседняя клетка того же ряда. Это учебная схема выдуманного района, а не географическая карта.</p>`);}
  function cityMap(mode='preview',gameId=''){const missing=mode==='listen'?[5,0,6]:[];return `<div class="city-map"><div class="city-heading"><span>BACK / ПОЗАДИ ↑</span><span>TONY’S DISTRICT / LEARNING MAP</span></div>${[0,1,2].map(r=>`${r===1?'<div class="city-lane"></div>':r===2?'<div class="city-road">MAIN STREET</div>':''}<div class="city-row">${D.map.slice(r*3,r*3+3).map((p,col)=>{const i=r*3+col;const hidden=missing.includes(i);return `<button class="city-building ${hidden?'missing':''}" data-city="${gameId}|${i}" ${mode==='preview'?'data-map-preview="true"':''} aria-label="${hidden?'Неизвестное место '+(i+1):esc(p.name)}${gameId?' — выбрать на карте':''}"><b>${hidden?'? '+(i+1):p.name}</b><small>${hidden?'название из аудио':p.ru}</small></button>`;}).join('')}</div>`).join('')}<p class="small">FRONT / ВХОДЫ ОБРАЩЕНЫ СЮДА ↓</p></div>`;}
  function prediction(){const opts=['shops','bank','bedroom','library','coffee','sofa','bus stop','window','post office'];return `<div class="choice-row">${opts.map(t=>`<button data-predict="${t}" class="${s.fields['predict:'+t]?'selected':''}" aria-pressed="${!!s.fields['predict:'+t]}">${t}</button>`).join('')}</div>`;}
  function listenControls(){return `<div class="actions"><button class="primary" data-listen>▷ LISTEN</button><button data-stop>STOP</button></div>`;}
  function transcript(){const tried=Object.keys(s.checks.listening||{}).length||s.games.radioMap?.attempted;return tried?fold('Transcript · после попытки',`<p lang="en">${D.radio}</p><p class="small">Старт — bank. Напротив него newsagent’s. Позади chemist’s — library. Напротив chemist’s — coffee shop.</p>`):'<p class="small">Текст скрыт до попытки в игре или Core Check. Преподаватель может прочитать его из Tutor Notes.</p>';}
  function streetFile(id=s.street){const f=D.streets.find(x=>x.id===id)||D.streets[0];return `<article class="street-file">${A.street(f.id)}<div class="street-copy"><div class="kicker">${f.theme}</div><h2>${f.title}</h2><p class="small"><b>${f.city}</b></p><p lang="en">${f.text}</p>${fold(f.title+' · Перевод',`<p>${f.ru}</p>`)}<small>Новый учебный текст по проверенным фактам: <a href="${f.source}" target="_blank" rel="noopener">официальный источник</a>${f.source2?` · <a href="${f.source2}" target="_blank" rel="noopener">Selfridges</a>`:''}.</small></div></article>`;}
  function streetSwitch(){return `<div class="game-switch">${D.streets.map(f=>`<button data-street="${f.id}" class="${s.street===f.id?'selected':''}" aria-pressed="${s.street===f.id}">${f.title}</button>`).join('')}</div>`;}
  function streetReading(){return `<h2>Три улицы. Сначала — зачем туда идти?</h2><p>Посмотри на названия. Где ожидаешь увидеть магазины, киноисторию, финансовый мир? Выбери файл: его текст и вопросы появятся рядом.</p>${note('Слова перед чтением',`<p><b>department store</b> — универмаг; <b>shop window</b> — витрина; <b>handprint / footprint</b> — отпечаток ладони / ступни; <b>cement</b> — цемент; <b>finance</b> — финансы; <b>economics</b> — экономика; <b>outdoor café</b> — кафе на открытом воздухе; <b>film museum</b> — музей кино; <b>narrow</b> — узкий.</p><p>В старом учебнике название кинотеатра Mann’s; в новом тексте используем его нынешнее название <b>TCL Chinese Theatre</b>. Списки магазинов старого издания не выдаём за актуальный путеводитель.</p>`)}${streetSwitch()}<div class="world-workspace">${streetFile()}${quiz('street-'+s.street)}</div>${keks('Not mentioned — текст об этом не сообщает. Это не то же самое, что False.')}`;}
  function quiz(id,items=D.quizzes[id]){const a=s.answers[id]||{},ch=s.checks[id]||{};return `<section class="quiz" data-quiz="${id}"><div class="kicker">CORE CHECK / ${items.length} ITEMS</div><h2>${id.startsWith('street-')?D.streets.find(f=>'street-'+f.id===id).title+' · задания':'Проверь дело'}</h2>${items.map((q,i)=>`<div class="q">${q.opts?`<div class="q-title">${i+1}. ${esc(q.p)}</div><div class="options" role="group" aria-label="${esc(q.p)}">${q.opts.map(v=>`<button data-choice="${id}|${i}|${esc(v)}" class="${a[i]===v?'selected':''}" aria-pressed="${a[i]===v}">${esc(v)}</button>`).join('')}</div>`:`<label for="wq-${id}-${i}">${i+1}. ${esc(q.p)}</label><input id="wq-${id}-${i}" data-answer="${id}|${i}" value="${esc(a[i]||'')}" autocomplete="off" spellcheck="false">`}<button class="quiet" data-hint="${id}|${i}">Need a Hint?</button>${s.hints[id+'|'+i]?`<p class="hint">${q.h}</p>`:''}${ch[i]===true?`<div class="feedback" role="status">✓ ${q.why}</div>`:ch[i]===false?`<div class="feedback wrong" role="status">↻ ${q.h}${(s.attempts[id+'|'+i]||0)>=2?`<br><button class="quiet" data-reveal="${id}|${i}">Показать ответ и объяснение</button>`:''}</div>`:''}${s.reveals[id+'|'+i]?`<p class="hint"><b>${esc(q.a[0])}</b> · ${q.why}</p>`:''}</div>`).join('')}<div class="actions"><button class="primary" data-check="${id}">CHECK</button><button data-retry="${id}">TRY AGAIN</button></div><div class="result" aria-live="polite">${Object.keys(ch).length?Object.values(ch).filter(Boolean).length+' / '+items.length+' верно':''}</div></section>`;}
  function play(id){
    if(id==='rooms')return `${pairGame('rooms')}${fold('Core Check · вспомни комнаты без списка',quiz(id))}`;
    if(id==='inventory')return `${mysteryGame()}${fold('Core Check · написание слов',quiz(id))}${fold('Extra Practice · все предметы гостиной',quiz('recall-furniture'))}${fold('Extra Practice · остальные предметы дома',quiz('recall-home'))}`;
    if(id==='grammar')return `${repairGame()}${fold('Core Check · выбираем по смыслу',quiz(id))}`;
    if(id==='place')return `${movingGame()}${fold('Core Check · наш план гостиной',A.room('',true)+quiz(id))}`;
    if(id==='moving')return `<div class="world-workspace">${dialogue()}${quiz(id)}</div>${fold('Phrase hunt · найди фразу в диалоге',phraseHunt())}`;
    if(id==='pronunciation')return `${soundGame()}${quiz(id)}${bridge('Прочитай where / who / what / when / whose. Где /w/ не слышно?','Преподаватель даёт ответ, ты подбираешь к нему вопрос.')}`;
    if(id==='roomExit')return `${A.room('',true)}${quiz(id)}${reflection('b',['Я называю комнаты и предметы.','Я описываю наличие с a/an, some и any.','Я различаю something / somebody.','Я могу объяснить расположение.','Я могу описать свою комнату.'])}`;
    if(id==='shops')return `${pairGame('shops')}${fold('Core Check · восстанови название',quiz(id))}${fold('Extra Practice · все 12 мест по памяти',quiz('recall-shops'))}`;
    if(id==='town')return `<div class="world-workspace"><article class="source-panel"><h3>Tony’s neighbourhood</h3><p lang="en">${D.townText}</p></article>${quiz(id)}</div>${mapQuest('townMap')}${mapLegend()}`;
    if(id==='listening')return `${listenControls()}${mapQuest('radioMap')}${quiz(id)}${transcript()}`;
    if(id==='delivery')return deliveryGame();
    if(id==='visitors')return `${visitorGame()}${streetSwitch()}<div class="world-workspace">${streetFile()}${quiz(id)}</div>`;
    if(id==='codes')return codeGame();
    return learn(id);
  }
  function use(id){const prompts={rooms:['This is my favourite room. It’s a…','Which room do you like? Why?'],inventory:['There’s a… in my… . There are some… .','Назови предмет; преподаватель придумает, где он может находиться. Потом поменяйтесь.'],grammar:['Опиши 3 вещи в своей или выдуманной комнате. Добавь одно отрицание и один вопрос.','Is there…? Are there any…? Ответь и задай встречный вопрос.'],place:['Put the… next to… . Put it between… and… .','Преподаватель выполняет инструкцию на плане. Уточни, если предмет оказался не там.'],shops:['I can buy… at the… . I can borrow… from the… .','What and where did you buy last week? Опора: I bought… at the… .'],delivery:['Excuse me, where can I buy…? Where is the…?','You can… at the… . It’s next to / opposite… . Смените роли.']};const p=prompts[id]||['Опиши один пример своими словами.','Задай преподавателю уточняющий вопрос.'];return `<h2>Your turn / теперь про тебя.</h2>${bridge(p[0],p[1])}${area(id+'-personal','Запиши опору, если нужно. Затем попробуй без неё.')}${fold('Extra Challenge',`<p>Измени одну деталь в ответе преподавателя и попроси заметить изменение. Укажи, что это выдуманный пример.</p>`)}`;}
  // GAME AND STUDIO IMPLEMENTATIONS
  function getGame(id,deck,ordered=false){return s.games[id]||(s.games[id]={deck:ordered?[...deck]:shuffle(deck),i:0,solved:[],attempts:0,ok:false});}
  const item=g=>g.deck[g.i];
  function gameSuccess(id,why,stage){const g=s.games[id];g.ok=true;g.feedback='✓ '+why;if(!g.solved.includes(g.i))g.solved.push(g.i);if(g.solved.length===g.deck.length){g.finished=true;if(stage)s.done[stage]=true;}save();}
  function roundPanel(id,g,title,body,hint){return `<section class="arcade" data-round="${id}"><div class="world-game-head"><div><div class="kicker">${g.finished?'✓ ROUND COMPLETE':'MISSION '+(g.i+1)+' / '+g.deck.length}</div><h2>${title}</h2></div><span class="score">${g.solved.length} / ${g.deck.length} верно</span></div>${body}${g.hint?`<div class="world-hint">${hint}</div>`:''}${g.feedback?`<div class="feedback ${g.ok?'':'wrong'}" role="status">${esc(g.feedback)}</div>`:''}<div class="actions"><button class="quiet" data-game-hint="${id}">Need a Hint?</button>${g.ok&&!g.finished?`<button class="primary" data-game-next="${id}">Следующее дело →</button>`:''}<button data-game-reset="${id}">TRY AGAIN · Новый раунд</button></div>${g.finished?'<div class="game-win">✓ Все задания раунда выполнены. Теперь используй слова в своей фразе.</div>':''}</section>`;}
  function pairGame(group){const id='pairs-'+group,words=D.words[group];const g=s.games[id]||(s.games[id]={round:0,matched:[],left:null,right:shuffle(Array.from({length:Math.min(6,words.length)},(_,i)=>i))});const ids=Array.from({length:Math.min(6,words.length-g.round*6)},(_,i)=>g.round*6+i);return `<section class="word-mission"><div class="kicker">WORD MATCH / ${g.matched.length} OF ${words.length}</div><h2>Соедини слово и значение.</h2><p>Нажми слово слева, затем перевод справа. Если не помнишь — выбери слово и открой Hint.</p><div class="lex-pairs"><div>${ids.map(i=>`<button data-pair-left="${group}|${i}" class="${g.left===i?'selected':''} ${g.matched.includes(i)?'paired':''}" ${g.matched.includes(i)?'disabled':''}>${words[i][0]} ${g.matched.includes(i)?'✓':''}</button>`).join('')}</div><div>${g.right.map(i=>`<button data-pair-right="${group}|${i}" class="${g.matched.includes(i)?'paired':''}" ${g.matched.includes(i)?'disabled':''}>${words[i][1]} ${g.matched.includes(i)?'✓':''}</button>`).join('')}</div></div>${g.feedback?`<div class="feedback ${g.bad?'wrong':''}" role="status">${g.feedback}</div>`:''}${g.hint?`<p class="hint">${g.left===null?'Выбери английское слово.':words[g.left][0]+' → '+words[g.left][1]}</p>`:''}<div class="actions"><button data-pair-hint="${group}">Need a Hint?</button>${ids.every(i=>g.matched.includes(i))&&(g.round+1)*6<words.length?`<button class="primary" data-pair-next="${group}">Следующие слова →</button>`:''}<button data-game-reset="${id}">TRY AGAIN</button></div>${g.matched.length===words.length?'<div class="game-win">✓ Все пары найдены.</div>':''}</section>`;}
  const mysteries=[{p:'I keep food cold. You usually find me in a kitchen.',a:'fridge',h:'Холодильник. Начало fr-.',why:'A fridge keeps food cold.'},{p:'You sleep on me. I am usually in a bedroom.',a:'bed',h:'Три буквы; начало b-.',why:'A bed is in a bedroom.'},{p:'I have shelves for books.',a:'bookcase',h:'Book + case.',why:'A bookcase holds books.'},{p:'You put your clothes inside me.',a:'wardrobe',h:'Шкаф для одежды. Начало war-.',why:'A wardrobe is for clothes.'},{p:'You use me to cook food in a kitchen.',a:'cooker',h:'Cook + er.',why:'A cooker is a kitchen appliance.'},{p:'You can look at yourself in me.',a:'mirror',h:'Зеркало. Начало mi-.',why:'A mirror shows your reflection.'},{p:'I am above your head in a room.',a:'ceiling',h:'Потолок. Начало cei-.',why:'Ceiling above, floor below.'},{p:'I am a comfortable chair with arms.',a:'armchair',h:'Arm + chair.',why:'An armchair — кресло.'}];
  function mysteryGame(){const id='mystery',g=getGame(id,mysteries),c=item(g);return roundPanel(id,g,'Object mystery',`<p>Не выбирай из списка: восстанови название по подсказке. Если сложно, открой Hint.</p><div class="clue-card"><small>WHO AM I?</small><strong>${c.p}</strong></div><label class="field">My answer<input data-game-input="${id}" value="${esc(g.input||'')}" autocomplete="off" spellcheck="false" ${g.ok?'disabled':''}></label><button class="primary" data-game-check="${id}" ${g.ok?'disabled':''}>CHECK</button>${g.attempts>=2&&!g.ok?`<button data-game-model="${id}">Разобрать слово</button>`:''}${g.model?`<p class="hint">${c.a}. ${c.why} Введи слово самостоятельно.</p>`:''}`,c.h);}
  const repairs=[{t:['There','are','a','sofa.'],bad:1,fix:'is',opts:['is','are','am'],why:'Один диван → There is a sofa.'},{t:['There','is','an','table.'],bad:2,fix:'a',opts:['a','an','any'],why:'Table начинается с согласного звука: a table.'},{t:['There','are','some','cushion.'],bad:3,fix:'cushions',opts:['cushions','cushion','a cushion'],why:'There are some + множественное число: cushions.'},{t:['Somebody','are','in','the','room.'],bad:1,fix:'is',opts:['is','are','am'],why:'Somebody грамматически в единственном числе: is.'},{t:['There','are','something','on','the','table.'],bad:1,fix:'is',opts:['is','are','am'],why:'Something + единственное число: There is something.'},{t:['There','is','a','furniture','in','the','room.'],bad:2,fix:'some',opts:['some','a','an'],why:'Furniture — неисчисляемое: some furniture, не a furniture.'}];
  function repairGame(){const id='repair',g=getGame(id,repairs),c=item(g);return roundPanel(id,g,'Inventory glitch hunt',`<p>В каждой записи одна ошибка. Нажми неверный фрагмент, затем выбери исправление.</p><div class="phrase-tokens">${c.t.map((t,i)=>`<button data-repair-token="${i}" class="${g.token===i?'found':''}" ${g.ok?'disabled':''}>${g.ok&&i===c.bad?esc(c.fix):t}</button>`).join('')}</div>${g.token===c.bad&&!g.ok?`<div class="choice-row">${c.opts.map(v=>`<button data-repair-fix="${v}">${v}</button>`).join('')}</div>`:''}`,'Проверь согласование is/are, число существительного и a/an/some. Something и somebody требуют единственного числа.');}
  const moves=[{object:'sofa',target:1,p:'Put the sofa in front of the window.',h:'Окно на дальней стене над клеткой B1. Нужное место — непосредственно у окна.',why:'B1 находится прямо перед окном.'},{object:'armchair',target:4,p:'Put the armchair between the fireplace and the door.',h:'Камин слева, дверь справа. Ищи клетку между ними в среднем ряду.',why:'B2 — между камином A2 и дверью C2.'},{object:'coffee table',target:7,p:'Put the coffee table in front of the armchair.',h:'Передняя часть плана внизу. Нужна клетка сразу перед креслом.',why:'B3 находится перед креслом B2.'},{object:'lamp',target:8,p:'Put the lamp next to the coffee table, on its right.',h:'Right = справа. Столик B3; возьми соседнюю клетку справа.',why:'C3 — справа от столика B3.'},{object:'carpet',target:7,p:'Put the carpet under the coffee table.',h:'Under = под. Для ковра и столика выбери одну и ту же клетку.',why:'Ковёр лежит в B3 под столиком.'}];
  const cellName=i=>'ABC'[i%3]+(Math.floor(i/3)+1);
  function placement(board={},action='move'){return `<div class="placement-board"><div class="placement-top">WINDOW / ОКНО</div><div class="placement-grid">${Array.from({length:9},(_,i)=>{const anchor=i===3?'fireplace':i===5?'door':'';return `<button class="placement-cell ${anchor?'anchor':''} ${(board[i]||[]).includes('carpet')?'carpetted':''}" data-${action}-cell="${i}" ${action==='move'&&anchor?'disabled':''} aria-label="Клетка ${cellName(i)}${anchor?' '+anchor:''}"><span>${cellName(i)}</span>${anchor?`<b>${anchor}</b>`:''}${(board[i]||[]).map(x=>`<b>${esc(x)}</b>`).join('')||(!anchor?'<small>выбрать место</small>':'')}</button>`;}).join('')}</div><p class="small">FRONT / ПЕРЕДНЯЯ ЧАСТЬ ПЛАНА ↓</p></div>`;}
  function movingGame(){const id='movingCrew',g=getGame(id,moves,true);g.board??={};const c=item(g);return roundPanel(id,g,'Move-in crew',`<p>Нажми нужное место на плане. Мебель остаётся на месте после каждого задания. Камин и дверь — постоянные ориентиры.</p><div class="parcel-card"><small>MOVE THIS OBJECT / ${c.object.toUpperCase()}</small><strong>${c.p}</strong></div>${placement(g.board)}`,c.h);}
  const mapClues=[{p:'Find the newsagent’s opposite the bank.',a:5,h:'Найди bank внизу справа; перейди через Main Street в тот же столбец.',why:'Newsagent’s — напротив bank, по другую сторону Main Street.'},{p:'Find the library behind the chemist’s.',a:0,h:'Behind — на ряд выше аптеки.',why:'Library расположена позади chemist’s.'},{p:'Find the coffee shop opposite the chemist’s.',a:6,h:'Из клетки chemist’s перейди через Main Street вниз.',why:'Coffee shop — напротив chemist’s.'},{p:'Find the post office next to the bank.',a:7,h:'Соседняя клетка в том же нижнем ряду.',why:'Post office — рядом с bank.'},{p:'Find the bus stop behind the supermarket.',a:1,h:'Остановка в верхнем ряду, над supermarket.',why:'Bus stop — позади supermarket.'}];
  function mapQuest(id){const g=getGame(id,id==='radioMap'?mapClues.slice(0,3):mapClues),c=item(g);return roundPanel(id,g,id==='radioMap'?'Listen & label':'Map detective',`<p>${id==='radioMap'?'Прослушай сообщение. Нажми клетку, где находится названное место. Названия трёх мест скрыты.':'Прочитай улику. Найди нужное здание на карте и нажми его.'}</p><div class="clue-card"><strong>${c.p}</strong></div>${cityMap(id==='radioMap'?'listen':'game',id)}`,c.h);}
  function deliveryGame(){const id='deliveryGame',g=getGame(id,D.deliveries),c=item(g);return roundPanel(id,g,'Delivery day',`<p>В этом выдуманном районе выбираем магазин по его специализации. Прочитай уточнение: оно поможет не выбирать супермаркет для всех случаев.</p><div class="parcel-card"><small>YOUR SHOPPING MISSION</small><strong>${c[0]}</strong><p>${c[2]}</p></div><div class="choice-row">${D.words.shops.map(([en])=>`<button data-deliver="${esc(en)}" ${g.ok?'disabled':''}>${en}</button>`).join('')}</div>`,c[3]);}
  const visitors=[{name:'David',p:'I study economics. I want to understand a place connected with finance.',a:'wall',why:'Economics / finance → Wall Street.'},{name:'Stella',p:'I enjoy shopping and looking at different shops.',a:'oxford',why:'Shopping → Oxford Street.'},{name:'Peter',p:'I love films and cinema history.',a:'hollywood',why:'Cinema history and star prints → Hollywood Boulevard.'},{name:'Claire',p:'I like fashion and looking for clothes.',a:'oxford',why:'Fashion and clothes → Oxford Street.'}];
  function visitorGame(){const id='visitorsGame',g=getGame(id,visitors),c=item(g);return roundPanel(id,g,'Find their street',`<p>Прочитай карточку посетителя и выбери подходящую улицу. Текстовые файлы ниже помогут доказать выбор.</p><div class="visitor-passport"><span class="monogram">${c.name[0]}</span><div><h3>${c.name}</h3><p lang="en">${c.p}</p></div></div><div class="street-choices">${D.streets.map(f=>`<button data-visitor="${f.id}" ${g.ok?'disabled':''}>${f.title}<br><small>${f.city}</small></button>`).join('')}</div>`,c.p.includes('finance')?'Найди файл о деньгах и финансах.':c.a==='hollywood'?'Найди файл о кино.':'Найди файл о магазинах и моде.');}
  function codeGame(){const id='codeGame',g=getGame(id,D.codes),c=item(g);return roundPanel(id,g,'Street code press',`<p>На марке — сокращение. Напечатай полную английскую форму.</p><div class="code-press"><strong>${c[0]}</strong><label class="field">Full word<input data-game-input="${id}" value="${esc(g.input||'')}" autocomplete="off" spellcheck="false" ${g.ok?'disabled':''}></label></div><button class="primary" data-game-check="${id}" ${g.ok?'disabled':''}>PRINT / CHECK</button>${g.attempts>=2&&!g.ok?`<button data-game-model="${id}">Открыть разбор</button>`:''}${g.model?`<p class="hint">${c[0]} = ${c[1]} · ${c[2]}. Введи слово самостоятельно.</p>`:''}`,`${c[2]}. Первая буква полного слова: ${c[1][0]}.`);}
  const soundWords=[['we',true],['win',true],['when',true],['why',true],['where',true],['who',false],['whose',false]];
  function soundGame(){const id='soundGame',g=getGame(id,soundWords),c=item(g);return roundPanel(id,g,'W: heard or silent?',`<p>Произнеси слово или послушай. Есть ли в нём звук /w/?</p><div class="parcel-card"><strong>${c[0]}</strong><button data-say="${c[0]}">▷ Listen</button></div><div class="choice-row"><button data-sound="yes" ${g.ok?'disabled':''}>/w/ слышно</button><button data-sound="no" ${g.ok?'disabled':''}>Буква w не произносится</button></div>`,'Who и whose начинаются с /h/. В остальных словах этого раунда есть /w/.');}
  const phraseTargets=[['Can you help me?','Can you give me a hand?'],['Hurry!','Quick, Dad!'],['That’s fantastic!','That’s great!'],['Take it easy!','Calm down, Mum.'],['What’s next?','What else?']];
  function phraseHunt(){const id='phraseHunt',g=getGame(id,phraseTargets),c=item(g);const choices=[...phraseTargets.map(x=>x[1])];return roundPanel(id,g,'Phrase hunt',`<p>Найди в диалоге выражение с тем же смыслом. Затем выбери его.</p><div class="parcel-card"><strong>${c[0]}</strong></div><div class="choice-row">${choices.map(x=>`<button data-phrase="${esc(x)}" ${g.ok?'disabled':''}>${x}</button>`).join('')}</div>`,'Смотри не на одинаковые слова, а на намерение говорящего: помощь, спешка, радость, спокойствие, следующий шаг.');}
  const wordCount=t=>(String(t).match(/[A-Za-zÀ-ž]+(?:['’\-][A-Za-zÀ-ž]+)*/g)||[]).length;
  function studio(id){
    if(id==='roomStudio'){const g=s.games.roomDesign||(s.games.roomDesign={selected:'sofa',board:{1:['sofa'],4:['armchair'],7:['coffee table']}});return `<h2>Твоя комната: план → разговор → текст.</h2><p>Это выдуманная комната, не настоящий адрес. Выбери предмет, затем клетку. Камин и дверь — ориентиры; размещай остальные предметы в свободных клетках. Повторный выбор перемещает предмет.</p><div class="choice-row">${['sofa','armchair','coffee table','lamp','carpet','bookcase','bed','computer'].map(x=>`<button data-design-item="${x}" class="${g.selected===x?'selected':''}">${x}</button>`).join('')}</div>${placement(g.board,'design')}<button data-design-clear>ОЧИСТИТЬ ПЛАН</button>${note('Модель для исходного плана',`<p class="example">There is a sofa in front of the window. There is an armchair between the fireplace and the door. The coffee table is in front of the armchair.</p><p>Если ты поменял(а) план, поменяй и описание. Когда предметы в одной клетке, уточни в тексте: lamp <b>on</b> the table или carpet <b>under</b> it.</p>`)}${bridge('Where do you want the sofa? — Put it… . Опиши свой выбор.','What about the armchair? — It looks better… . Преподаватель уточняет одну позицию.')}${area('roomText','My living room · напиши 4–6 предложений','In my living room, there is…\nThere are some…\nThe… is next to…')}${checkList('roomCheck',['Я назвал(а) комнату и предметы.','Есть there is / there are и нужное a/an/some/any.','Расположение в тексте соответствует моему плану.','Я прочитал(а) описание и обсудил(а) его с преподавателем.'])}${area('roomTutor','Tutor feedback · одна удачная фраза и одно улучшение')}<div class="actions"><button class="primary" data-complete-studio="roomStudio">СОХРАНИТЬ ПОСЛЕ ОБСУЖДЕНИЯ</button><button data-download="roomText">СКАЧАТЬ ТЕКСТ .TXT</button></div>`;}
    if(id==='townStudio'){const g=s.games.townDesign||(s.games.townDesign={selected:'post office',board:{7:'post office',8:'bank',4:'supermarket'}});return `<h2>Мой район / My neighbourhood.</h2><p>Собери выдуманную карту. Выбери место, затем клетку; новая подпись заменяет прежнюю. Улицу Main Street оставим между двумя нижними рядами.</p><div class="choice-row">${[...D.words.shops.map(x=>x[0]),'coffee shop','bus stop'].map(x=>`<button data-town-item="${esc(x)}" class="${g.selected===x?'selected':''}">${x}</button>`).join('')}</div>${townDesign(g)}<button data-town-clear>ОЧИСТИТЬ КАРТУ</button>${mapLegend()}${note('Опоры для собственного текста',`<p>I live in a… neighbourhood. There is a… next to the… . Opposite the…, there is a… . You can buy / get / borrow… at / from the… . I like it because… .</p><p>Сначала опиши 2–3 места, затем добавь, что там можно получить. Не надо придумывать факты о реальном городе: можно оставить район выдуманным.</p>`)}${area('townText','My neighbourhood · 5–7 предложений','I live in…\nThere is…\nThe… is opposite…')}${bridge('Проведи короткую экскурсию по своей карте.','Преподаватель спрашивает: Where can I buy…? Is there a… near…?')}${checkList('townCheck',['На карте названы хотя бы три места.','В описании есть next to / opposite / behind.','Текст соответствует моей карте.','Я объяснил(а), что можно получить в одном из мест.'])}${area('townTutor','Tutor feedback')}<div class="actions"><button class="primary" data-complete-studio="townStudio">ОБСУДИЛИ · СОХРАНИТЬ</button><button data-download="townText">СКАЧАТЬ ТЕКСТ .TXT</button></div>${reflection('c',['Я называю магазины.','Я различаю купить и взять на время.','Я нахожу места на карте.','Я понимаю короткое сообщение о районе.','Я могу описать свой район.'])}`;}
    return `<h2>Твой туристический мини-гид.</h2><p>Выбери настоящую улицу своего города или придумай учебную. Итог — <b>60–70 английских слов</b>. Для реальной улицы проверь факты; для выдуманной честно укажи, что это fiction.</p><div class="guide-fields">${input('guideStreet','Street name','Maple Street')}${input('guideCity','Town / city','My town')}${input('guideLocation','Location','in the centre')}${input('guideShops','Places you can find','a bakery, a bookshop and two cafés')}</div>${area('guideActivities','Что там можно делать?','You can…')}${area('guideSource','Источник фактов или пометка «выдуманная улица»')}${fold('Прочитать модель · выдуманная Maple Street',`<p lang="en">${D.modelGuide}</p><p class="small">${wordCount(D.modelGuide)} слов. Это учебный пример; не описание реального города.</p>`)}${note('Структура мини-гида',`<ol><li><b>Location:</b> где улица находится?</li><li><b>Places:</b> что там есть?</li><li><b>Position:</b> где одно место относительно другого?</li><li><b>Activities:</b> что можно делать?</li><li><b>Personal ending:</b> почему советуешь это место?</li></ol><p>Не заполняй объём пустыми словами. Дай читателю полезные детали. Изображения на странице — учебные графические иллюстрации, не фотографии этих улиц.</p>`)}${area('guideText','My tourist guide · 60–70 слов','… Street is in…\nThere are…\nYou can…')}<div class="word-counter"><b>WORD COUNT / ОРИЕНТИР 60–70</b><span id="guide-count">${wordCount(value('guideText'))}</span></div><div class="actions"><button data-guide-preview>ПОКАЗАТЬ МОЙ ГИД</button><button data-download="guideText">СКАЧАТЬ .TXT</button></div><div id="guide-preview">${s.open.guidePreview?`<article class="preview"><b>${esc(value('guideStreet','Maple Street'))}</b><p>${esc(value('guideText')).replace(/\n/g,'<br>')}</p></article>`:''}</div>${checkList('guideCheck',['Я указал(а) местоположение.','Есть места/магазины и хотя бы одно расположение.','Есть занятия для посетителя.','Проверены факты или указано, что улица выдуманная.','Преподаватель помог проверить язык.'])}${area('guideTutor','Tutor feedback')}<button class="primary" data-complete-studio="guide">ОБСУДИЛИ · ЗАВЕРШИТЬ ГИД</button><p class="small">Сайт считает слова и сохраняет текст. Смысл и точность английского проверяются с преподавателем. Кнопка не публикует текст в интернете.</p>${reflection('d',['Я различаю три улицы по их особенностям.','Я нахожу подтверждение в тексте.','Я различаю False и Not mentioned.','Я расшифровываю сокращения адресов.','Я могу написать короткий гид.'])}`;
  }
  function townDesign(g){return `<div class="city-map"><div class="city-heading"><span>MY LEARNING MAP</span><span>BACK ↑</span></div>${[0,1,2].map(r=>`${r===1?'<div class="city-lane"></div>':r===2?'<div class="city-road">MAIN STREET</div>':''}<div class="city-row">${[0,1,2].map(c=>{const i=r*3+c;return `<button class="city-building" data-town-cell="${i}" aria-label="${cellName(i)}, ${esc(g.board[i]||'пусто')}"><b>${esc(g.board[i]||'+ PLACE')}</b><small>${cellName(i)}</small></button>`;}).join('')}</div>`).join('')}</div>`;}
  function reflection(unitId,items){return `<section class="editor-reflection"><h3>Exit ticket / честная рефлексия</h3>${items.map((t,i)=>`<div class="q"><b>${t}</b><div class="choice-row">${[['yes','Самостоятельно'],['hint','С подсказкой'],['again','Повторить']].map(([v,label])=>`<button data-reflect="${unitId}|${i}|${v}" class="${value('reflect:'+unitId+i)===v?'selected':''}" aria-pressed="${value('reflect:'+unitId+i)===v}">${label}</button>`).join('')}</div></div>`).join('')}${area('goal-'+unitId,'Один шаг на следующий урок')}</section>`;}
  function checkQuiz(id){const qs=D.quizzes[id],a=s.answers[id]||{};if(qs.some((_,i)=>!String(a[i]||'').trim())){toast('Ответь на все вопросы. Подсказки доступны.');return;}const ch={};qs.forEach((q,i)=>{ch[i]=q.a.some(v=>norm(v)===norm(a[i]));if(!ch[i])s.attempts[id+'|'+i]=(s.attempts[id+'|'+i]||0)+1;});s.checks[id]=ch;if(D.stages[id])s.done[id]=Object.values(ch).every(Boolean)||mastered(id);if(id.startsWith('street-'))s.done.streets=D.streets.every(f=>D.quizzes['street-'+f.id].every((_,i)=>s.checks['street-'+f.id]?.[i]===true));save();render();toast(Object.values(ch).every(Boolean)?'✓ Всё верно. Попробуй использовать язык сам(а).':'Ответы проверены. Под ошибками есть помощь.');}
  function mastered(stage){const ids={rooms:['pairs-rooms'],inventory:['mystery'],grammar:['repair'],place:['movingCrew'],shops:['pairs-shops'],town:['townMap'],delivery:['deliveryGame'],codes:['codeGame']};return (ids[stage]||[]).some(id=>s.games[id]?.finished);}
  function resetView(){return `<h2 id="world-dialog-title">Новый ученик?</h2><p>Очистятся ответы, заметки, планы, тексты и прогресс <b>всего курса: Module 1 и 2a–2d</b> в этом браузере.</p><div class="actions"><button class="primary" data-confirm-reset>RESET ALL · ОЧИСТИТЬ</button><button data-close>ОТМЕНА</button></div>`;}
  function tutorView(){return `<h2 id="world-dialog-title">Tutor notes / ${unit().code}</h2><p><b>Формат:</b> 1 ученик + преподаватель, 11–12 лет, A1+ с поддержкой → A2. ${unit().time}.</p><p><b>Итог:</b> ${unit().outcome}</p><p>Core Route: короткий контекст → нужное объяснение → одна основная игра или Core Check → личный ответ. Дополнительные словарные серии не нужно выполнять подряд. 2b лучше разделить на два занятия: комнаты/предметы/количества, затем расположение/диалог/вопросы/описание.</p>${fold('Скрипт нового аудирования 2c · читать дважды',`<p lang="en">${D.radio}</p><p>Первая попытка: старт в bank. Вторая: расположение. Это авторский учебный текст, не отсутствующая аудиозапись учебника.</p>`)}${fold('Открытые задания',`<p>Описание комнаты: 4–6 предложений. Район: 5–7 предложений. Гид: 60–70 слов. Сначала сравните текст и план, затем поправьте одну форму. Автоматической оценки смысла или грамматики у текстов нет.</p>`)}${fold('Answer keys / Core Check',Object.entries(D.quizzes).filter(([id])=>unit().stages.includes(id)||s.unit==='d'&&id.startsWith('street-')).map(([id,qs])=>`<h3>${id}</h3><ol>${qs.map(q=>`<li>${esc(q.p)} → <b>${esc(q.a.join(' / '))}</b></li>`).join('')}</ol>`).join(''))}${area('tutor-'+s.unit,'Заметки преподавателя · только на этом устройстве')}<p class="small">При отсутствии голоса устройства читайте модели сами. Оригинальная аудиозапись учебника не имитируется. Карты и комнаты — новые учебные схемы, их задания проверяются именно по ним.</p>`;}
  function completeStudio(id){const cfg={roomStudio:['roomText','roomCheck',4],townStudio:['townText','townCheck',4],guide:['guideText','guideCheck',5]}[id];if(!cfg)return;const[key,prefix,n]=cfg;if(!String(value(key)).trim()||!Array.from({length:n},(_,i)=>value(prefix+i)).every(Boolean)){toast('Добавь свой текст и пройди чек-лист с преподавателем.');return;}if(id==='townStudio'&&Object.keys(s.games.townDesign?.board||{}).length<3){toast('На карте нужны хотя бы три места.');return;}if(id==='guide'&&(wordCount(value(key))<60||wordCount(value(key))>70)){toast('Для этого проекта нужно 60–70 английских слов. Сейчас: '+wordCount(value(key))+'.');return;}s.done[id]=true;save();render();toast('✓ Результат сохранён после обсуждения.');}
  function bind(){
    const all=(sel,fn)=>root.querySelectorAll(sel).forEach(el=>el.onclick=()=>fn(el));
    root.querySelectorAll('[data-fold]').forEach(el=>el.ontoggle=()=>{if(!!s.open[el.dataset.fold]!==el.open){s.open[el.dataset.fold]=el.open;save();}});
    all('[data-home]',()=>route(s.unit));all('[data-stage]',b=>route(s.unit,b.dataset.stage));all('[data-tab]',b=>route(s.unit,s.stage,b.dataset.tab));all('[data-step]',b=>{const i=unit().stages.indexOf(s.stage)+(+b.dataset.step);route(s.unit,unit().stages[i]||null);});
    all('[data-modal]',b=>{lastFocus=document.activeElement;modal=b.dataset.modal;stop();render();});all('[data-close]',closeModal);all('[data-confirm-reset]',()=>{stop();document.querySelector('.toast')?.remove();courseKeys.forEach(k=>{try{localStorage.removeItem(k);}catch{}});s=fresh();modal='';history.replaceState(null,'','#b');render();window.scrollTo(0,0);toast('Новый ученик. Весь курс очищен.');});
    root.querySelectorAll('[data-field]').forEach(el=>el.addEventListener(el.type==='checkbox'||el.tagName==='SELECT'?'change':'input',()=>{s.fields[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;save();if(el.dataset.field==='guideText'){const c=root.querySelector('#guide-count');if(c)c.textContent=wordCount(el.value);const p=root.querySelector('#guide-preview');if(p&&s.open.guidePreview)p.innerHTML='<article class="preview"><p>'+esc(el.value).replace(/\n/g,'<br>')+'</p></article>';}}));
    all('[data-word]',b=>{const[g,i]=b.dataset.word.split('|');s.open['word:'+g+i]=!s.open['word:'+g+i];save();render();});all('[data-word-group]',b=>{s.wordGroup=b.dataset.wordGroup;save();render();});all('[data-say]',b=>speak(b.dataset.say));all('[data-listen]',()=>speak(D.radio));all('[data-stop]',stop);
    const inspect=name=>{if(D.words.furniture.some(x=>x[0]===name)){s.object=name;if(!s.stage){route('b','rooms');return;}save();render();}};all('[data-object]',b=>inspect(b.dataset.object));all('[data-room-object]',b=>inspect(b.dataset.roomObject));root.querySelectorAll('[data-room-object]').forEach(el=>el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect(el.dataset.roomObject);}});all('[data-labels]',()=>{s.labels=!s.labels;save();render();});
    root.querySelectorAll('[data-answer]').forEach(el=>el.oninput=()=>{const[id,i]=el.dataset.answer.split('|');s.answers[id]??={};s.answers[id][i]=el.value;if(s.checks[id])delete s.checks[id][i];if(!mastered(id))delete s.done[id];if(id.startsWith('street-'))delete s.done.streets;save();el.closest('.q').querySelector('.feedback')?.remove();el.closest('.quiz').querySelector('.result').textContent='Ответ изменён. Нажми Check.';});
    all('[data-choice]',b=>{const[id,i,v]=b.dataset.choice.split('|');s.answers[id]??={};s.answers[id][i]=v;if(s.checks[id])delete s.checks[id][i];if(!mastered(id))delete s.done[id];if(id.startsWith('street-'))delete s.done.streets;save();render();});all('[data-check]',b=>checkQuiz(b.dataset.check));all('[data-hint]',b=>{s.hints[b.dataset.hint]=!s.hints[b.dataset.hint];save();render();});all('[data-reveal]',b=>{s.reveals[b.dataset.reveal]=true;save();render();});all('[data-retry]',b=>{const id=b.dataset.retry;delete s.answers[id];delete s.checks[id];if(!mastered(id))delete s.done[id];if(id.startsWith('street-'))delete s.done.streets;for(const k of ['attempts','hints','reveals'])Object.keys(s[k]).filter(x=>x.startsWith(id+'|')).forEach(x=>delete s[k][x]);save();render();});
    all('[data-game-hint]',b=>{const g=s.games[b.dataset.gameHint];g.hint=!g.hint;save();render();});all('[data-game-model]',b=>{s.games[b.dataset.gameModel].model=true;save();render();});all('[data-game-reset]',b=>{delete s.games[b.dataset.gameReset];save();render();});all('[data-game-next]',b=>{const g=s.games[b.dataset.gameNext];if(!g.ok||g.i>=g.deck.length-1)return;g.i++;for(const k of ['feedback','ok','input','hint','token','model'])delete g[k];g.attempts=0;save();render();});root.querySelectorAll('[data-game-input]').forEach(el=>el.oninput=()=>{const g=s.games[el.dataset.gameInput];g.input=el.value;g.ok=false;save();});
    all('[data-game-check]',b=>{const id=b.dataset.gameCheck,g=s.games[id],c=item(g);g.attempts++;if(norm(g.input)===''){toast('Введи слово.');return;}const ans=id==='codeGame'?c[1]:c.a;if(norm(g.input)===norm(ans))gameSuccess(id,id==='codeGame'?`${c[0]} = ${c[1]} · ${c[2]}`:c.why,id==='codeGame'?'codes':'inventory');else{g.ok=false;g.feedback='↻ '+(id==='codeGame'?c[2]+'. Первая буква: '+c[1][0]:c.h);}save();render();});
    all('[data-pair-left]',b=>{const[group,i]=b.dataset.pairLeft.split('|'),g=s.games['pairs-'+group];g.left=+i;g.feedback='';g.hint=false;save();render();});all('[data-pair-right]',b=>{const[group,i]=b.dataset.pairRight.split('|'),g=s.games['pairs-'+group];if(g.left===null){toast('Сначала выбери английское слово.');return;}g.bad=g.left!==+i;g.feedback=g.bad?'↻ Значения не совпали. Попробуй ещё.':'✓ '+D.words[group][g.left][0]+' = '+D.words[group][g.left][1];if(!g.bad){if(!g.matched.includes(g.left))g.matched.push(g.left);g.left=null;if(g.matched.length===D.words[group].length){g.finished=true;s.done[group==='rooms'?'rooms':'shops']=true;}}save();render();});all('[data-pair-hint]',b=>{const g=s.games['pairs-'+b.dataset.pairHint];g.hint=!g.hint;save();render();});all('[data-pair-next]',b=>{const group=b.dataset.pairNext,g=s.games['pairs-'+group];g.round++;g.right=shuffle(Array.from({length:Math.min(6,D.words[group].length-g.round*6)},(_,i)=>g.round*6+i));g.left=null;g.feedback='';g.hint=false;save();render();});
    all('[data-repair-token]',b=>{const g=s.games.repair,c=item(g);g.token=+b.dataset.repairToken;g.feedback=g.token===c.bad?'':'Этот фрагмент подходит. Проверь другой.';save();render();});all('[data-repair-fix]',b=>{const g=s.games.repair,c=item(g);if(b.dataset.repairFix===c.fix)gameSuccess('repair',c.why,'grammar');else{g.feedback='↻ Проверь число, глагол или неисчисляемое существительное.';g.ok=false;}save();render();});
    all('[data-move-cell]',b=>{const g=s.games.movingCrew;if(g.ok)return;const c=item(g),n=+b.dataset.moveCell;if(n===c.target){g.board[n]??=[];if(!g.board[n].includes(c.object))g.board[n].push(c.object);gameSuccess('movingCrew',c.why,'place');}else{g.ok=false;g.feedback='↻ '+c.h;}save();render();});
    all('[data-city]',b=>{const[id,i]=b.dataset.city.split('|');if(!id){toast(D.map[+i].name+' — '+D.map[+i].ru);return;}const g=s.games[id];if(!g||g.ok)return;g.attempted=true;const c=item(g);if(+i===c.a)gameSuccess(id,c.why,id==='townMap'?'town':null);else{g.ok=false;g.feedback='↻ '+c.h;}save();render();});
    all('[data-deliver]',b=>{const g=s.games.deliveryGame,c=item(g);if(norm(b.dataset.deliver)===norm(c[1]))gameSuccess('deliveryGame',c[3],'delivery');else{g.ok=false;g.feedback='↻ Прочитай уточнение поручения и выбери специализированное место.';}save();render();});all('[data-visitor]',b=>{const g=s.games.visitorsGame,c=item(g);if(b.dataset.visitor===c.a)gameSuccess('visitorsGame',c.why,null);else{g.ok=false;g.feedback='↻ Найди в тексте занятие, которое интересно посетителю.';}save();render();});all('[data-sound]',b=>{const g=s.games.soundGame,c=item(g);if((b.dataset.sound==='yes')===c[1])gameSuccess('soundGame',c[1]?c[0]+' начинается с /w/.':c[0]+' начинается с /h/; w не произносится.',null);else{g.ok=false;g.feedback='↻ Сравни со who /huː/ и when /wen/.';}save();render();});all('[data-phrase]',b=>{const g=s.games.phraseHunt,c=item(g);if(b.dataset.phrase===c[1])gameSuccess('phraseHunt',c[0]+' → '+c[1],null);else{g.ok=false;g.feedback='↻ Проверь смысл фразы, а не только похожие слова.';}save();render();});
    all('[data-code]',b=>{s.open['code'+b.dataset.code]=!s.open['code'+b.dataset.code];save();render();});all('[data-street]',b=>{s.street=b.dataset.street;save();render();});all('[data-predict]',b=>{const k='predict:'+b.dataset.predict;if(!s.fields[k]&&Object.keys(s.fields).filter(x=>x.startsWith('predict:')&&s.fields[x]).length>=6){toast('Выбери не больше шести слов.');return;}s.fields[k]=!s.fields[k];save();render();});
    all('[data-design-item]',b=>{s.games.roomDesign.selected=b.dataset.designItem;save();render();});all('[data-design-cell]',b=>{const g=s.games.roomDesign,n=+b.dataset.designCell;if(n===3||n===5){toast('Камин и дверь оставим свободными. Выбери другую клетку.');return;}Object.keys(g.board).forEach(k=>{g.board[k]=g.board[k].filter(x=>x!==g.selected);if(!g.board[k].length)delete g.board[k];});g.board[n]??=[];g.board[n].push(g.selected);save();render();});all('[data-design-clear]',()=>{s.games.roomDesign.board={};save();render();});all('[data-town-item]',b=>{s.games.townDesign.selected=b.dataset.townItem;save();render();});all('[data-town-cell]',b=>{s.games.townDesign.board[b.dataset.townCell]=s.games.townDesign.selected;save();render();});all('[data-town-clear]',()=>{s.games.townDesign.board={};save();render();});
    all('[data-guide-preview]',()=>{if(!String(value('guideText')).trim()){toast('Сначала напиши свой гид.');return;}s.open.guidePreview=true;save();render();});all('[data-complete-studio]',b=>completeStudio(b.dataset.completeStudio));all('[data-reflect]',b=>{const[u,i,v]=b.dataset.reflect.split('|');s.fields['reflect:'+u+i]=v;save();render();});all('[data-download]',b=>{const t=String(value(b.dataset.download)).trim();if(!t){toast('Сначала напиши текст.');return;}const a=document.createElement('a'),u=URL.createObjectURL(new Blob([t],{type:'text/plain;charset=utf-8'}));a.href=u;a.download=b.dataset.download+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);});
  }
  function closeModal(){const which=modal;modal='';render();root.querySelector('[data-modal="'+which+'"]')?.focus();}
  document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const els=[...root.querySelectorAll('.dialog button,.dialog input,.dialog textarea,.dialog summary')].filter(x=>!x.disabled&&(!x.closest('details')||x.tagName==='SUMMARY'||x.closest('details').open));if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els[els.length-1]?.focus();}else if(!e.shiftKey&&document.activeElement===els[els.length-1]){e.preventDefault();els[0]?.focus();}}});
  window.addEventListener('hashchange',()=>{stop();readHash();save();render();window.scrollTo(0,0);});window.addEventListener('pagehide',stop);
  readHash();render();

})();
